<?php

namespace App\Integration\Console\Commands;

use App\Integration\Models\WebhookEndpoint;
use Illuminate\Console\Command;

/**
 * I-04's minting path — no admin screen exists yet for this, same gap
 * App\Integration\Console\Commands\CreateApiTokenCommand already leaves for
 * I-01's own credential. The signing secret is generated by
 * WebhookEndpoint::booted() and printed here once; unlike a Sanctum token it
 * stays in the database in plaintext, because every delivery has to sign
 * against it again — see the model's own docblock.
 */
class CreateWebhookEndpointCommand extends Command
{
    protected $signature = 'webhook-endpoint:create
        {url : The receiving endpoint that outbound webhooks POST to}
        {--event=* : One or more event types this endpoint subscribes to, e.g. ProjectBooked}';

    protected $description = 'Registers a WebhookEndpoint and prints its signing secret once.';

    public function handle(): int
    {
        $endpoint = WebhookEndpoint::create([
            'url' => $this->argument('url'),
            'subscribed_events' => $this->option('event'),
        ]);

        $this->info("Created WebhookEndpoint {$endpoint->public_id} for {$endpoint->url}.");
        $this->line("Secret (store this — shown once): {$endpoint->secret}");

        return self::SUCCESS;
    }
}
